12	    pub(crate) fn z_order(&self, x_: f64, y_: f64) -> i32 {
13	        // coords are transformed into non-negative 15-bit integer range
14	        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
15	        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;
16	
17	        x = (x | (x << 8)) & 0x00FF_00FF;
18	        x = (x | (x << 4)) & 0x0F0F_0F0F;
19	        x = (x | (x << 2)) & 0x3333_3333;
20	        x = (x | (x << 1)) & 0x5555_5555;
21	
22	        y = (y | (y << 8)) & 0x00FF_00FF;
23	        y = (y | (y << 4)) & 0x0F0F_0F0F;
24	        y = (y | (y << 2)) & 0x3333_3333;
25	        y = (y | (y << 1)) & 0x5555_5555;
26	
27	        x | (y << 1)
28	    }
